""","""// Storage is ISO 8601 text, so a string comparison against "now" orders correctly.
function visibleTo<Q extends { whereNull(f: 'publishedAt'): Q; orWhere(f: string, op: string, v: unknown): Q }>(
  q: Q,
  viewerId: number | null,
): Q {
  q.whereNull('publishedAt').orWhere('publishedAt', '<=', new Date().toISOString())
  if (viewerId !== null) q.orWhere('authorId', viewerId)
  return q
}

function scheduleFields(publishAt: string | null | undefined): { publishedAt: string | null } {
  return { publishedAt: publishAt ? new Date(publishAt).toISOString() : null }
}

export default class PostController extends Controller {
  private async viewerId(): Promise<number | null> {
    const user = await this.auth.user<UserRecord>()
    return user ? Number(user.id) : null
  }

""")
